// YouTube と Twitch の配信を見守り、コメントとお知らせを時間順に画面へ渡す。
(() => {
  const YOUTUBE = "https://www.youtube.com";
  const TWITCH = "wss://irc-ws.chat.twitch.tv:443";
  const TWITCH_GQL = "https://gql.twitch.tv/gql";
  const VIDEO_ID = /^[\w-]{11}$/;
  const TWITCH_NAME = /^[a-z\d_]{1,25}$/i;
  const OFFLINE_WAIT = 60000;
  const KEEP_READING = new Set(["superchat", "sticker", "member", "gift", "bits", "sub", "raid"]);
  const VOICEVOX_MISSING = "VOICEVOX が見つかりません（起動してください）";
  const YOUTUBE_UNKNOWN = "YouTube の配信ページでチャットが開けるか確かめてください。1 分後にもう一度つなぎます";
  const input = (value) => typeof value === "string" ? value.trim() : "";
  const plain = (value, max = 500) => typeof value === "string" ?
    Array.from(value.replace(/<!--[\s\S]*?-->|<[/!]?[a-z][^>]*>/gi, "")).slice(0, max).join("") : "";

  function siteUrl(value) {
    try {
      const url = new URL(/^https?:\/\//i.test(value) ? value : "https://" + value);
      if (!url.username && !url.password && !url.port) return url;
    } catch {}
    return null;
  }

  function youtubeTarget(value) {
    value = input(value);
    const handle = /^@[\p{L}\p{M}\p{N}_.·-]{1,100}$/u;
    const handlePath = (name) => ({ path: "/@" + encodeURIComponent(name.slice(1)) + "/live" });
    if (handle.test(value)) return handlePath(value);
    const url = siteUrl(value);
    if (!url) return null;
    const [, first = "", second = ""] = url.pathname.split("/");
    const short = url.hostname === "youtu.be";
    if (!short && !["youtube.com", "www.youtube.com", "m.youtube.com"].includes(url.hostname)) return null;
    const videoId = short ? first : first === "watch" ? url.searchParams.get("v") : ["live", "embed"].includes(first) ? second : "";
    if (videoId && VIDEO_ID.test(videoId)) return { videoId };
    if (short) return null;
    let name;
    try { name = decodeURIComponent(first); } catch { return null; }
    if (handle.test(name)) return handlePath(name);
    if (["channel", "c", "user"].includes(first) && /^[\w.-]{1,100}$/.test(second)) return { path: "/" + first + "/" + second + "/live" };
    return null;
  }

  function twitchChannel(value) {
    value = input(value);
    if (TWITCH_NAME.test(value)) return value.toLowerCase();
    const url = siteUrl(value);
    if (!url || !["twitch.tv", "www.twitch.tv", "m.twitch.tv"].includes(url.hostname)) return "";
    const name = /^\/([a-z\d_]+)\/?$/i.exec(url.pathname)?.[1];
    return name && TWITCH_NAME.test(name) ? name.toLowerCase() : "";
  }

  function youtubeText(value) {
    if (typeof value === "string") return value;
    if (typeof value?.simpleText === "string") return value.simpleText;
    return (value?.runs || []).map(({ text, emoji }) => {
      if (typeof text === "string") return text;
      if (!emoji) return "";
      if (!emoji.isCustomEmoji) return emoji.emojiId || emoji.shortcuts?.[0] || "";
      const name = emoji.shortcuts?.[0] || emoji.searchTerms?.[0] || "絵文字";
      return ":" + name.replace(/^:+|:+$/g, "") + ":";
    }).join("");
  }

  function youtubeColor(value) {
    return Number.isInteger(value) ? "#" + (value & 0xffffff).toString(16).padStart(6, "0") : "";
  }

  function youtubeBadges(value) {
    const badges = [];
    for (const { liveChatAuthorBadgeRenderer: badge } of value || []) {
      const icon = badge?.icon?.iconType, title = badge?.tooltip || "";
      if (icon === "OWNER" || /^(owner|channel owner|チャンネル所有者)$/i.test(title)) badges.push("owner");
      else if (icon === "MODERATOR" || /moderator|モデレーター/i.test(title)) badges.push("moderator");
      else if (badge?.customThumbnail || /member|メンバー/i.test(title)) badges.push("member");
    }
    return [...new Set(badges)];
  }

  const YOUTUBE_ITEMS = [
    ["liveChatTextMessageRenderer", "chat"],
    ["liveChatPaidMessageRenderer", "superchat"],
    ["liveChatPaidStickerRenderer", "sticker"],
    ["liveChatMembershipItemRenderer", "member"],
    ["liveChatSponsorshipsGiftPurchaseAnnouncementRenderer", "gift"],
    ["liveChatSponsorshipsGiftRedemptionAnnouncementRenderer", "gift"],
  ];

  function youtubeItem(item, now) {
    for (const [type, kind] of YOUTUBE_ITEMS) {
      const data = item?.[type];
      if (!data?.id) continue;
      const header = data.header?.liveChatSponsorshipsHeaderRenderer;
      const author = plain(youtubeText(data.authorName || header?.authorName), 128);
      const body = youtubeText(data.message);
      let text = body;
      if (kind === "sticker") text = data.sticker?.accessibility?.accessibilityData?.label || "スーパーステッカー";
      if (kind === "member") {
        const membership = [data.headerPrimaryText, data.headerSubtext].map(youtubeText).filter(Boolean).join(" ");
        text = [membership || "メンバーに加入しました", body].filter(Boolean).join(" ");
      }
      if (kind === "gift") text = youtubeText(header?.primaryText) || body || "メンバーシップギフト";
      const amount = plain(youtubeText(data.purchaseAmountText), 64);
      const color = youtubeColor(data.authorNameTextColor);
      const highlight = youtubeColor(data.headerBackgroundColor ?? data.moneyChipBackgroundColor ?? data.backgroundColor ?? data.bodyBackgroundColor);
      const badges = youtubeBadges(data.authorBadges || header?.authorBadges);
      const time = Math.floor(Number(data.timestampUsec) / 1000);
      const authorId = data.authorExternalChannelId || header?.authorExternalChannelId;
      return {
        id: data.id, source: "youtube", author, text: plain(text), time: Number.isFinite(time) ? time : now, kind,
        ...(authorId && { authorId }),
        ...(amount && { amount }), ...(color && { color }), ...(highlight && { highlight }), ...(badges.length && { badges }),
      };
    }
    return null;
  }

  function readContinuation(list) {
    for (const entry of list || []) {
      const next = entry.timedContinuationData || entry.invalidationContinuationData || entry.reloadContinuationData;
      if (typeof next?.continuation === "string" && next.continuation) {
        return { token: next.continuation, wait: Number.isFinite(next.timeoutMs) ? Math.max(0, next.timeoutMs) : 1000 };
      }
    }
    return null;
  }

  function youtubeChat(data, now = Date.now()) {
    const chat = data?.continuationContents?.liveChatContinuation;
    const changes = [], added = [];
    for (const action of chat?.actions || []) {
      const replaced = action.replaceChatItemAction;
      const id = action.removeChatItemAction?.targetItemId || action.markChatItemAsDeletedAction?.targetItemId;
      const authorId = action.removeChatItemByAuthorAction?.externalChannelId ||
        action.markChatItemsByAuthorAsDeletedAction?.externalChannelId;
      if (id) changes.push({ remove: { id } });
      if (authorId) changes.push({ remove: { authorId } });
      const item = youtubeItem(action.addChatItemAction?.item || replaced?.replacementItem, now);
      if (replaced?.targetItemId && replaced.targetItemId !== item?.id) changes.push({ remove: { id: replaced.targetItemId } });
      if (!item) continue;
      changes.push(item);
      if (action.addChatItemAction) added.push(item);
    }
    const next = readContinuation(chat?.continuations);
    return { changes, added, next, ended: !!chat && !next };
  }

  // ページのスクリプトが持つ JSON だけを取り出す。中の JavaScript は動かさない。
  function readJsonAt(html, start) {
    if (html[start] !== "{") return null;
    let depth = 0, quoted = false;
    for (let i = start; i < html.length; i++) {
      const ch = html[i];
      if (quoted) {
        if (ch === "\\") i++;
        else if (ch === '"') quoted = false;
      } else if (ch === '"') quoted = true;
      else if (ch === "{") depth++;
      else if (ch === "}" && --depth === 0) {
        try { return JSON.parse(html.slice(start, i + 1)); } catch { return null; }
      }
    }
    return null;
  }

  function youtubePage(html) {
    const data = {};
    for (const match of html.matchAll(/\b(ytInitialData|ytInitialPlayerResponse)(?:["']\])?\s*=\s*/g)) {
      const value = readJsonAt(html, match.index + match[0].length);
      if (value) data[match[1]] = value;
    }
    const config = Object.assign({}, ...Array.from(html.matchAll(/\bytcfg\.set\(\s*/g),
      (match) => readJsonAt(html, match.index + match[0].length)));
    return { data: data.ytInitialData, player: data.ytInitialPlayerResponse, config };
  }

  // null は配信していないと分かったとき。undefined はページから判断できないとき。
  function youtubeLive(page, videoId) {
    const details = page.player?.videoDetails;
    const broadcast = page.player?.microformat?.playerMicroformatRenderer?.liveBroadcastDetails;
    const chat = page.data?.contents?.twoColumnWatchNextResults?.conversationBar?.liveChatRenderer;
    const id = details?.videoId || videoId;
    if (broadcast?.endTimestamp || chat?.isReplay || page.player?.playabilityStatus?.status === "LIVE_STREAM_OFFLINE") return null;
    if (details?.isLive !== true && broadcast?.isLiveNow !== true) {
      if (broadcast?.isLiveNow === false || details?.isLive === false || details?.isLiveContent === false ||
          (!id && page.data?.metadata?.channelMetadataRenderer && page.data?.contents?.twoColumnBrowseResultsRenderer)) return null;
      return undefined;
    }
    if (!VIDEO_ID.test(id || "")) return undefined;
    // チャットの読み始めには、表示切り替え用の値ではなく、チャット本体の続きを使う。
    const next = readContinuation(chat?.continuations);
    return { id, name: plain(details?.title || details?.author || id, 120), next };
  }

  const isViewerCount = (value) => Number.isSafeInteger(value) && value >= 0;

  function youtubeViewerCount(renderer) {
    if (!renderer || renderer.isLive === false) return undefined;
    const original = renderer.originalViewCount;
    if (isViewerCount(original)) return original;
    const originalText = typeof original === "string" ? original.normalize("NFKC").trim() : "";
    if (/^(?:\d{1,3}(?:[, ]\d{3})+|\d+)$/.test(originalText)) {
      const count = Number(originalText.replace(/[, ]/g, ""));
      if (isViewerCount(count)) return count;
    }
    const value = renderer.viewCount;
    const direct = typeof value === "string" ? value : value?.simpleText;
    const runs = Array.isArray(value?.runs) ? value.runs : [];
    const text = typeof direct === "string" ? direct :
      runs.map((run) => typeof run?.text === "string" ? run.text : "").join("");
    const label = text.normalize("NFKC").trim();
    const match = /^(?:現在\s*)?(\d{1,3}(?:[, ]\d{3})+|\d+)(\.\d+)?\s*([千万億kmb])?\s*(?:人が視聴中|watching(?: now)?)$/i.exec(label);
    if (!match) return undefined;
    const [, digits, decimal = "", unit = ""] = match;
    if (decimal && !unit) return undefined;
    const multiplier = { 千: 1e3, 万: 1e4, 億: 1e8, k: 1e3, m: 1e6, b: 1e9 }[unit.toLowerCase()] ?? 1;
    const count = Math.round(Number(digits.replace(/[, ]/g, "") + decimal) * multiplier);
    return isViewerCount(count) ? count : undefined;
  }

  function youtubePageViewers(data) {
    const contents = data?.contents?.twoColumnWatchNextResults?.results?.results?.contents;
    if (!Array.isArray(contents)) return undefined;
    const primary = contents.find((item) => item?.videoPrimaryInfoRenderer)?.videoPrimaryInfoRenderer;
    return youtubeViewerCount(primary?.viewCount?.videoViewCountRenderer);
  }

  function youtubeMetadataViewers(data) {
    for (const action of Array.isArray(data?.actions) ? data.actions : []) {
      const count = youtubeViewerCount(action?.updateViewershipAction?.viewCount?.videoViewCountRenderer);
      if (count !== undefined) return count;
    }
    // 2026-11 の YouTube は人数を frameworkUpdates の viewCountEntity に入れて返す（actions には無い）。
    // 「〇 人が視聴中」の文があるときだけ使う（再生回数の「〇 回視聴」を人数と取り違えないため）。
    const mutations = data?.frameworkUpdates?.entityBatchUpdate?.mutations;
    for (const mutation of Array.isArray(mutations) ? mutations : []) {
      const entity = mutation?.payload?.viewCountEntity;
      if (!entity) continue;
      const count = youtubeViewerCount({ viewCount: entity.viewCount });
      if (count === undefined) continue;
      const exact = Number(entity.viewCountNumber);
      return isViewerCount(exact) ? exact : count;
    }
    return undefined;
  }

  // null は配信していないと確認できたとき。通信や応答の問題は undefined。
  function twitchViewers(data) {
    if (data?.errors?.length) return undefined;
    const stream = data?.data?.user?.stream;
    if (stream === null) return null;
    return isViewerCount(stream?.viewersCount) ? stream.viewersCount : undefined;
  }

  const TAG_ESCAPE = { s: " ", ":": ";", r: "\r", n: "\n", "\\": "\\" };
  function ircLine(line) {
    const parsed = /^(?:@([^ ]+) +)?(?::([^ ]+) +)?([^ ]+)(?: +([^]*))?$/.exec(line);
    if (!parsed) return {};
    const [, raw = "", prefix = "", command, rest = ""] = parsed;
    const tags = Object.fromEntries(raw.split(";").filter(Boolean).map((tag) => {
      const index = tag.indexOf("=");
      return index < 0 ? [tag, ""] : [tag.slice(0, index), tag.slice(index + 1).replace(/\\(.)/g, (_, ch) => TAG_ESCAPE[ch] ?? ch)];
    }));
    const split = rest.startsWith(":") ? 0 : rest.indexOf(" :");
    const args = split < 0 ? rest : rest.slice(0, split);
    const text = split < 0 ? "" : rest.slice(split + (split === 0 ? 1 : 2));
    return { tags, prefix, command, args, text };
  }

  function twitchMembership({ command, prefix, args, text }, channel) {
    if (command !== "JOIN" && command !== "PART") return null;
    if ((args || text).toLowerCase() !== "#" + channel) return null;
    const nick = prefix.split("!")[0].toLowerCase();
    if (!TWITCH_NAME.test(nick) || nick.startsWith("justinfan")) return null;
    return { command, nick };
  }

  function twitchMembershipNotices(events) {
    const groups = new Map();
    for (const { command, nick } of events) {
      if (!groups.has(command)) groups.set(command, []);
      groups.get(command).push(nick);
    }
    return [...groups].flatMap(([command, nicks]) => {
      const ending = command === "JOIN" ? "がチャットに来ました" : "がチャットを離れました";
      if (nicks.length >= 4) {
        const [a, b] = nicks;
        return [{ text: `Twitch：${a} さん・${b} さんほか ${nicks.length - 2} 人${ending}` }];
      }
      return nicks.map((nick) => ({ text: `Twitch：${nick} さん${ending}` }));
    });
  }

  const TWITCH_BADGES = { broadcaster: "owner", moderator: "moderator", subscriber: "subscriber", founder: "subscriber", vip: "vip" };
  const TWITCH_NOTICES = {
    sub: "sub", resub: "sub", subgift: "gift", anonsubgift: "gift", submysterygift: "gift",
    anonsubmysterygift: "gift", primepaidupgrade: "sub", giftpaidupgrade: "sub", anongiftpaidupgrade: "sub", raid: "raid",
  };

  function withoutEmotes(text, tag) {
    if (!tag) return text;
    const chars = [...text];
    for (const entry of tag.split("/")) {
      const ranges = entry.split(":")[1] || "";
      for (const range of ranges.split(",")) {
        if (!/^\d+-\d+$/.test(range)) continue;
        const [start, end] = range.split("-").map(Number);
        if (start <= end && end < chars.length) chars.fill(" ", start, end + 1);
      }
    }
    return chars.join("");
  }

  function twitchItem({ tags, prefix, command, text }, now = Date.now()) {
    if (!["PRIVMSG", "USERNOTICE"].includes(command) || !tags.id) return null;
    const bits = Number(tags.bits);
    const hasBits = command === "PRIVMSG" && Number.isSafeInteger(bits) && bits > 0;
    const notice = tags["msg-id"];
    const noticeKind = Object.hasOwn(TWITCH_NOTICES, notice) ? TWITCH_NOTICES[notice] : "system";
    const kind = command === "USERNOTICE" ? noticeKind : hasBits ? "bits" : "chat";
    const system = tags["system-msg"];
    const body = text.replace(/^\x01ACTION |\x01$/g, "");
    const withNotice = (value) => command === "USERNOTICE" ? [system, value].filter(Boolean).join(" ") : value;
    const message = withNotice(body);
    if (!message && kind === "system") return null;
    const badges = [...new Set((tags.badges || "").split(",").map((badge) => TWITCH_BADGES[badge.split("/")[0]])
      .filter((badge) => typeof badge === "string"))];
    const color = /^#[a-f\d]{6}$/i.test(tags.color) ? tags.color : "";
    const time = tags["tmi-sent-ts"] ? Number(tags["tmi-sent-ts"]) : NaN;
    const authorId = tags["user-id"], login = (tags.login || (command === "PRIVMSG" ? prefix.split("!")[0] : "")).toLowerCase();
    return {
      id: tags.id, source: "twitch", author: plain(tags["display-name"] || tags.login || tags["msg-param-displayName"] || prefix.split("!")[0], 128),
      text: plain(message), time: Number.isFinite(time) ? time : now, kind,
      ...(authorId && { authorId }), ...(login && { login }),
      ...(tags.emotes && { speech: plain(withNotice(withoutEmotes(body, tags.emotes))) }),
      ...(hasBits && { amount: bits.toLocaleString("ja-JP") + " Bits" }), ...(color && { color }), ...(badges.length && { badges }),
    };
  }

  function twitchRemoval({ command, tags, text }) {
    if (command === "CLEARMSG" && tags["target-msg-id"]) return { id: tags["target-msg-id"] };
    if (command === "CLEARCHAT") {
      if (tags["target-user-id"]) return { authorId: tags["target-user-id"], login: text.toLowerCase() };
      if (text) return { login: text.toLowerCase() };
      return {};
    }
    return null;
  }

  function mergeItems(before, after) {
    const byId = new Map([...before, ...after].map((item) => [item.source + ":" + item.id, item]));
    return [...byId.values()].sort((a, b) => a.time - b.time).slice(-200);
  }

  function createFirstComments() {
    const ids = new Set(), names = new Set(), namesWithoutId = new Set();
    return (item, fresh) => {
      if (item.kind === "notice" || item.kind === "system") return false;
      const name = input(item.author);
      if (item.authorId) {
        const seen = ids.has(item.authorId) || namesWithoutId.delete(name);
        ids.add(item.authorId);
        if (name) names.add(name);
        return fresh && !seen;
      }
      if (!name || names.has(name)) return false;
      names.add(name);
      namesWithoutId.add(name);
      return fresh;
    };
  }

  function createViewerStats() {
    const sources = { youtube: { samples: [] }, twitch: { samples: [] } };
    let total = [], peak;

    function sample(samples, count, time) {
      if (samples.at(-1)?.time === time) samples.pop();
      samples.push({ time, count });
      while (samples[0].time < time - 120000) samples.shift();
    }

    function box(samples) {
      const latest = samples.at(-1);
      if (!latest) return { text: "—" };
      const result = { text: String(latest.count) };
      const target = latest.time - 60000;
      if (samples[0].time > target) return result;
      let closest, distance = 30001;
      for (const entry of samples) {
        const diff = Math.abs(entry.time - target);
        if (diff < distance) { closest = entry; distance = diff; }
      }
      if (closest) {
        const delta = latest.count - closest.count;
        result.sub = delta === 0 ? "±0" : delta > 0 ? "+" + delta : String(delta);
      }
      return result;
    }

    function sum(time, coverageChanged) {
      // 片方を取れなくなったときは、同じ配信元を合計した値から比べ直す。
      if (coverageChanged) total = [];
      const counts = Object.values(sources).flatMap(({ samples }) => samples.length ? [samples.at(-1).count] : []);
      if (!counts.length) return;
      const count = counts.reduce((a, b) => a + b);
      sample(total, count, time);
      if (!peak || count > peak.count) peak = { count, time };
    }

    return {
      stream(source, id, time) {
        const state = sources[source];
        if (state.stream === id) return;
        const other = sources[source === "youtube" ? "twitch" : "youtube"];
        if (state.stream && !other.stream) peak = undefined;
        sources[source] = { stream: id, samples: [] };
        if (state.samples.length) sum(time, true);
      },
      update(source, count, time, riseStep) {
        const state = sources[source];
        const hadCount = state.samples.length > 0;
        if (!isViewerCount(count)) {
          if (hadCount) {
            state.samples = [];
            sum(time, true);
          }
          return;
        }
        sample(state.samples, count, time);
        sum(time, !hadCount);
        const baseline = state.baseline ?? count;
        const step = Number.isFinite(riseStep) ? Math.max(1, Math.min(20, Math.round(riseStep))) : 3;
        if (count - baseline >= step) {
          state.baseline = count;
          const name = source === "youtube" ? "YouTube" : "Twitch";
          return { text: `${name} の視聴者が ${count - baseline} 人増えました（${baseline} → ${count}）`, up: true };
        }
        state.baseline = Math.min(baseline, count);
      },
      stats() {
        return {
          youtube: box(sources.youtube.samples), twitch: box(sources.twitch.samples), total: box(total),
          peak: peak ? {
            text: String(peak.count),
            sub: new Date(peak.time).toTimeString().slice(0, 5),
          } : { text: "—" },
        };
      },
    };
  }

  function speechText(item, { ttsReadName = true, ttsMaxChars = 50 } = {}) {
    const youtube = item.source === "youtube";
    function clean(text) {
      const links = (text || "").replace(/(?:https?:\/\/|www\.)[^\s<>"'「」『』【】（）。、！？…\p{Extended_Pictographic}]+/giu, "URL");
      const words = youtube ? links.replace(/:[\p{L}\p{M}\p{N}_.+~\-]+:/gu, "") : links;
      return words.replace(/[#*\d]\uFE0F?\u20E3|\p{Extended_Pictographic}|\p{Emoji_Modifier}|\p{Regional_Indicator}|[\u200D\uFE0E\uFE0F\u{E0020}-\u{E007F}]/gu, "")
        .replace(/\s+/g, " ").trim();
    }
    const body = item.kind === "sticker" ? "スーパーステッカー" : clean(item.speech ?? item.text);
    if (!body && !KEEP_READING.has(item.kind)) return "";
    const name = ttsReadName ? clean(item.author) : "";
    const author = youtube ? name.replace(/^@+/, "") : name;
    const chars = [...(author ? author + "さん" + (body ? "、" + body : "") : body)];
    const max = Number.isInteger(ttsMaxChars) ? Math.max(10, Math.min(200, ttsMaxChars)) : 50;
    const ending = "以下略";
    return chars.length > max ? chars.slice(0, Math.min(max, 200 - ending.length)).join("").trimEnd() + ending : chars.join("");
  }

  async function youtubeGet(api, path, current) {
    let url = new URL(path, YOUTUBE);
    for (let i = 0; i < 5 && current(); i++) {
      const response = await api.fetch(url.href, { redirect: "manual", headers: { "accept-language": "ja" } });
      const location = response.headers?.location;
      if (response.status >= 300 && response.status < 400 && location) {
        url = new URL(location, url);
        if (url.origin !== YOUTUBE || url.username || url.password) break;
      } else {
        return { ...response, url };
      }
    }
    return { ok: false, status: 0 };
  }

  function pollViewers(interval, load, receive, delay = interval) {
    let stopped = false, timer = setTimeout(poll, delay);
    async function poll() {
      const started = Date.now();
      let count;
      try { count = await load(); } catch {}
      if (stopped) return;
      receive(count);
      if (!stopped) timer = setTimeout(poll, Math.max(0, interval - (Date.now() - started)));
    }
    return () => {
      stopped = true;
      clearTimeout(timer);
    };
  }

  function startYoutube(api, target, job, update, monitor) {
    const watchPath = (id) => "/watch?v=" + id + "&hl=ja";
    const current = () => !job.stopped;
    const later = (work, delay) => { if (current()) job.timer = setTimeout(work, delay); };
    let live, context, endpoint, headers, viewerVideo, viewerRequest;
    function endStream() {
      job.stopViewers?.();
      job.stopViewers = undefined;
      viewerVideo = undefined;
      monitor.stream(null);
    }
    function watchViewers(page, videoId) {
      if (viewerVideo !== videoId) {
        job.stopViewers?.();
        job.stopViewers = undefined;
        viewerVideo = videoId;
        monitor.stream(videoId);
        monitor.viewers(youtubePageViewers(page.data));
      }
      if (!context?.client?.clientVersion) return;
      const metadata = new URL(endpoint.href);
      metadata.pathname = "/youtubei/v1/updated_metadata";
      viewerRequest = [metadata.href, { method: "POST", headers, body: JSON.stringify({ context, videoId }) }];
      job.stopViewers ??= pollViewers(30000, async () => {
        const response = await api.fetch(...viewerRequest);
        if (response.ok) return youtubeMetadataViewers(JSON.parse(response.text));
      }, monitor.viewers);
    }
    async function discover() {
      const startedAt = Date.now();
      job.playerId = "";
      try {
        const response = await youtubeGet(api, target.videoId ? watchPath(target.videoId) : target.path + "?hl=ja", current);
        if (!current()) return;
        if (response.status === 404 || response.status === 410) {
          update("配信ページが見つかりません。名前か URL を確かめてください。1 分後に再確認します", [], "warn");
          later(discover, OFFLINE_WAIT);
          return;
        }
        if (!response.ok) throw new Error();
        const page = youtubePage(response.text);
        live = youtubeLive(page, target.videoId || response.url.searchParams.get("v"));
        if (live === null) {
          endStream();
          update("配信していません。1 分ごとに確かめます");
          later(discover, OFFLINE_WAIT);
          return;
        }
        if (!live) throw new Error();
        const config = page.config;
        context = config.INNERTUBE_CONTEXT;
        endpoint = new URL("/youtubei/v1/live_chat/get_live_chat", YOUTUBE);
        // 公開ページの値を使うので、使う人が鍵を作る必要はない。
        if (config.INNERTUBE_API_KEY) endpoint.searchParams.set("key", config.INNERTUBE_API_KEY);
        headers = { "content-type": "application/json", "accept-language": "ja", origin: YOUTUBE };
        if (config.INNERTUBE_CONTEXT_CLIENT_NAME) headers["x-youtube-client-name"] = String(config.INNERTUBE_CONTEXT_CLIENT_NAME);
        if (context?.client?.clientVersion) headers["x-youtube-client-version"] = context.client.clientVersion;
        if (context?.client?.visitorData) headers["x-goog-visitor-id"] = context.client.visitorData;
        watchViewers(page, live.id);
        if (!live.next || !context?.client?.clientVersion) throw new Error();
        job.playerId = live.id || "";
        update(live.name + " の配信につないでいます…");
        // 配信ページから得た値で、最初からチャットの API に問い合わせる。
        await poll(live.next.token, startedAt, true);
      } catch {
        if (!current()) return;
        job.playerId = "";
        update(YOUTUBE_UNKNOWN, [], "warn");
        later(discover, OFFLINE_WAIT);
      }
    }
    function receive({ changes, added, next, ended }, startedAt, first) {
      // 初回は一覧を埋めるための履歴。表示の差し替えも読み直さない。
      const fresh = first ? [] : added.filter((item) => item.time >= startedAt);
      if (ended) {
        job.playerId = "";
        update(live.name + " の配信が終わりました", changes, "ok", fresh);
        endStream();
        later(discover, OFFLINE_WAIT);
      } else {
        if (!next) throw new Error();
        update(live.name + " の配信につながりました", changes, "ok", fresh);
        later(() => poll(next.token, startedAt), Math.max(100, next.wait));
      }
    }
    async function poll(token, startedAt, first = false) {
      try {
        const response = await api.fetch(endpoint.href, { method: "POST", headers, body: JSON.stringify({ context, continuation: token }) });
        if (!current()) return;
        if (!response.ok) throw new Error();
        receive(youtubeChat(JSON.parse(response.text)), startedAt, first);
      } catch {
        if (!current()) return;
        job.playerId = "";
        update("コメントを読み込めません。15 秒後につなぎ直します", [], "warn");
        later(discover, 15000);
      }
    }
    discover();
  }

  function startTwitch(api, channel, job, update, monitor) {
    let retry = 1000;
    const current = () => !job.stopped;
    job.stopViewers = pollViewers(60000, async () => {
      const response = await api.fetch(TWITCH_GQL, {
        method: "POST",
        headers: { "Client-Id": "kimne78kx3ncx6brgo4mv6wki5h1ko", "content-type": "application/json" },
        body: JSON.stringify({
          query: "query($login:String!){user(login:$login){stream{viewersCount}}}",
          variables: { login: channel },
        }),
      });
      if (response.ok) return twitchViewers(JSON.parse(response.text));
    }, (count) => {
      if (count !== undefined) monitor.stream(count === null ? null : channel);
      monitor.viewers(count);
    }, 0);
    function reconnect() {
      if (!current()) return;
      job.playerId = "";
      update(channel + " に再接続します", [], "warn");
      job.timer = setTimeout(connect, retry);
      retry = Math.min(retry * 2, 60000);
    }
    function connect() {
      update(channel + " につないでいます…");
      let ws;
      try { ws = new WebSocket(TWITCH); }
      catch { reconnect(); return; }
      job.socket = ws;
      job.timer = setTimeout(() => ws.close(), 15000);
      let joinedAt = Infinity;
      const joined = () => {
        if (joinedAt !== Infinity) return;
        joinedAt = Date.now();
        clearTimeout(job.timer);
        retry = 1000;
        job.playerId = channel;   // IRC の接続。ライブかどうかは公式プレーヤーが表示する
        update(channel + " に接続中");
      };
      const nick = "justinfan" + Math.floor(10000 + Math.random() * 990000);
      ws.onopen = () => {
        if (!current()) return;
        ws.send("CAP REQ :twitch.tv/tags twitch.tv/commands twitch.tv/membership\r\n");
        ws.send("PASS SCHMOOPIIE\r\n");
        ws.send("NICK " + nick + "\r\n");
      };
      ws.onmessage = ({ data }) => {
        if (!current() || job.socket !== ws) return;
        const changes = [], fresh = [], membership = [];
        for (const line of data.split(/\r?\n/)) {
          const message = ircLine(line);
          if (message.command === "PING") ws.send("PONG :" + (message.text || message.args) + "\r\n");
          if (message.command === "001") ws.send("JOIN #" + channel + "\r\n");
          if (message.command === "ROOMSTATE" && message.args === "#" + channel) joined();
          if (message.command === "RECONNECT") { ws.close(); break; }
          const event = twitchMembership(message, channel);
          if (event) membership.push(event);
          if (message.args !== "#" + channel) continue;
          const remove = twitchRemoval(message);
          if (remove) changes.push({ remove });
          const item = twitchItem(message);
          if (item) {
            changes.push(item);
            if (item.time >= joinedAt) fresh.push(item);
          }
        }
        if (changes.length) update(channel + " に接続中", changes, "ok", fresh);
        if (membership.length) monitor.membership(membership);
      };
      ws.onclose = () => {
        if (job.socket !== ws) return;
        clearTimeout(job.timer);
        job.socket = null;
        reconnect();
      };
    }
    connect();
  }

  function createReading(api, report) {
    const seen = new Set();
    let config = {}, waiting = [], active, draining = false, stopping;
    let revision = 0, checkTimer, engineError = "", speechError = "";

    function trimWaiting() {
      const max = Number.isInteger(config.ttsMaxWaiting) ? Math.max(1, Math.min(20, config.ttsMaxWaiting)) : 5;
      while (waiting.length > max) {
        const index = waiting.findIndex((item) => !KEEP_READING.has(item.kind));
        if (index < 0) break;
        waiting.splice(index, 1);
      }
    }

    async function say(item) {
      const { text, source } = item;
      const started = revision;
      let error = "";
      try {
        const result = await api.speak({ text, speaker: source === "youtube" ? config.voiceYoutube : config.voiceTwitch,
          speed: config.ttsSpeed, pitch: config.ttsPitch, volume: config.ttsVolume, output: config.ttsOutput });
        if (!result.ok) error = result.error || "読み上げに失敗しました";
      } catch { error = "読み上げに失敗しました"; }
      if (started === revision && !item.cancelled) {
        if (error === VOICEVOX_MISSING && config.ttsOn) engineError = error;
        speechError = error === VOICEVOX_MISSING && config.ttsOn ? "" : error;
        report();
      }
    }

    function stopSpeech() {
      if (active) active.cancelled = true;
      stopping ??= Promise.resolve(api.speakStop()).catch(() => {}).finally(() => { stopping = undefined; });
    }

    async function drain() {
      if (draining || !config.ttsOn) return;
      draining = true;
      try {
        while (waiting.length && config.ttsOn) {
          if (stopping) { await stopping; continue; }
          active = waiting.shift();
          await say(active);
          active = undefined;
        }
      } finally { draining = false; }
    }

    async function check() {
      const started = revision;
      let error;
      try {
        const result = await api.voicevox();
        error = result.ok ? "" : result.error || VOICEVOX_MISSING;
      } catch { error = VOICEVOX_MISSING; }
      if (started !== revision) return;
      engineError = error;
      report();
      checkTimer = setTimeout(check, 5000);
    }

    return {
      error: () => engineError || speechError,
      settings(next, paused) {
        const before = config.ttsOn === true;
        config = paused ? { ...next, ttsOn: false } : next;
        if (paused || (before && !config.ttsOn)) {
          revision++;
          clearTimeout(checkTimer);
          waiting = [];
          engineError = speechError = "";
          stopSpeech();
        } else if (!before && config.ttsOn) {
          speechError = "";
          void check();
        }
        trimWaiting();
      },
      resetSource(source) { waiting = waiting.filter((item) => item.source !== source); },
      remove(matches) {
        waiting = waiting.filter((item) => !matches(item));
        if (active && !active.cancelled && matches(active)) stopSpeech();
      },
      receive(items, fresh) {
        const live = new Set(fresh);
        for (const item of items) {
          if (item.kind === "notice") continue;
          const id = item.source + ":" + item.id;
          if (seen.has(id)) continue;
          seen.add(id);
          if (!config.ttsOn || !live.has(item) || item.kind === "system") continue;
          const text = speechText(item, config);
          if (!text) continue;
          waiting.push({ ...item, text });
          trimWaiting();
          void drain();
        }
      },
      test() { void say({ text: "これは読み上げのテストです", source: "youtube" }); },
    };
  }

  function startComments(api) {
    const sources = {
      youtube: { name: "YouTube", parse: youtubeTarget, start: startYoutube },
      twitch: { name: "Twitch", parse: twitchChannel, start: startTwitch },
    };
    let list = [], timer = null, next = api.settings, waiting = false;
    const monitorApp = api.monitorApp;
    let appState, usingApp = false;
    let connected = api.onObs ? null : false, streaming = null, revision = 0, obsTimer;
    let noticeId = 0;
    const viewers = createViewerStats();
    const reading = createReading(api, report);
    const waitText = () => connected === true ? "配信が始まるのを待っています" : "OBS の接続を待っています";
    function report() {
      if (timer !== null) return;
      timer = setTimeout(() => {
        timer = null;
        if (usingApp) {
          const status = appState.status ?? { text: "", level: "", list: [], stats: {} };
          api.status({ ...status, text: "配信モニター（アプリ）から：" + status.text });
          return;
        }
        const appPrompt = next.useApp !== false && appState?.state === "waiting" ?
          "・配信モニター（アプリ）で、線画アバターの接続を許可してください" : "";
        const stats = viewers.stats();
        if (waiting) {
          api.status({ level: "", text: waitText() + appPrompt, list, stats });
          return;
        }
        const states = Object.values(sources);
        const speechError = reading.error();
        const messages = states.filter((s) => s.text !== "未設定").map((s) => s.text.startsWith(s.name + " ") ? s.text : s.name + "：" + s.text);
        if (!messages.length) messages.push("チャンネルを入れて「つなぐ」を押してください");
        if (speechError) messages.push("読み上げ：" + speechError);
        const videos = Object.fromEntries(Object.entries(sources).map(([key, source]) => [key, source.job?.playerId || ""]));
        api.status({ level: speechError || states.some((s) => s.level === "warn") ? "warn" : "ok", text: messages.join("・") + appPrompt, list, videos, stats });
      }, 110);
    }
    function stopSource(key, source) {
      if (!source.job) return;
      const { job } = source;
      source.job = null;
      job.stopped = true;
      clearTimeout(job.timer);
      job.stopViewers?.();
      job.socket?.close();
      viewers.stream(key, null, Date.now());
    }
    function addNotices(source, notices, time) {
      const items = notices.map((notice) => ({ id: "notice-" + ++noticeId, source, kind: "notice", time, ...notice }));
      if (!items.length) return;
      list = mergeItems(list, items);
      report();
    }
    function receive(key, job, changes, fresh) {
      let items = [];
      const live = new Set(fresh);
      const firstIds = new Set(list.filter((item) => item.source === key && item.first).map((item) => item.id));
      for (const change of changes) {
        const { remove } = change;
        if (!remove) {
          const first = job.stream !== null && job.first(change, live.has(change));
          if (job.deleted.has(change.id)) continue;
          if (next.markFirst !== false && (first || firstIds.has(change.id))) {
            change.first = true;
            firstIds.add(change.id);
          }
          items.push(change);
          continue;
        }
        const { id, authorId, login } = remove;
        if (id) job.deleted.add(id);
        const matches = (item) => {
          if (item.source !== key || item.kind === "notice") return false;
          if (id && item.id !== id) return false;
          // Twitch の通知と投稿のどちらかにユーザー ID が無いときは、ログイン名で照合する。
          if (authorId && (item.authorId || !login) && item.authorId !== authorId) return false;
          if (login && (!authorId || !item.authorId) && item.login !== login) return false;
          job.deleted.add(item.id);
          return true;
        };
        list = list.filter((item) => !matches(item));
        items = items.filter((item) => !matches(item));
        reading.remove(matches);
      }
      // 同じ応答で削除された新着は、読み上げを始める前に除く。
      if (items.length) {
        list = mergeItems(list, items);
        reading.receive(items, fresh);
      }
    }
    function sync() {
      if (monitorApp && !appState && next.useApp !== false) return;
      if (next.useApp !== false && appState?.state === "connected") {
        if (!usingApp) {
          usingApp = true;
          for (const [key, source] of Object.entries(sources)) stopSource(key, source);
          list = [];
          reading.settings(next, true);
        }
        report();
        return;
      }
      usingApp = false;
      const hold = next.autoConnect === true && (connected !== true || streaming !== true);
      if (!hold || !waiting) reading.settings(next, hold);
      if (hold) list = [];
      waiting = hold;
      for (const [key, source] of Object.entries(sources)) {
        const value = input(next[key]), target = source.parse(value);
        const signature = JSON.stringify([target, !target && value]);
        if (signature !== source.signature) {
          source.signature = signature;
          reading.resetSource(key);
          stopSource(key, source);
          list = list.filter((item) => item.source !== key);
        }
        if (waiting) { stopSource(key, source); continue; }
        if (source.job) continue;
        source.text = !value ? "未設定" : key === "youtube" ? "@名前 か配信の URL を入れてください" : "チャンネル名か twitch.tv のチャンネル URL を入れてください";
        source.level = value ? "warn" : "";
        if (target) {
          const job = { deleted: new Set(), first: createFirstComments() };
          source.job = job;
          source.text = "配信を確かめています…";
          source.level = "";
          source.start(api, target, job, (text, changes = [], level = "ok", fresh = []) => {
            if (job.stopped) return;
            source.text = text;
            source.level = level;
            if (changes.length) receive(key, job, changes, fresh);
            report();
          }, {
            stream(id) {
              if (job.stream === id) return;
              if (job.stream !== undefined) job.first = createFirstComments();
              job.stream = id;
              viewers.stream(key, id, Date.now());
              report();
            },
            viewers(count) {
              const time = Date.now();
              const notice = viewers.update(key, count, time, next.riseStep);
              if (notice) addNotices(key, [notice], time);
              report();
            },
            membership(events) {
              if (next.showJoins !== false) addNotices(key, twitchMembershipNotices(events), Date.now());
            },
          });
        }
      }
      report();
    }
    async function readStream() {
      clearTimeout(obsTimer);
      const started = ++revision;
      const result = await api.obs("GetStreamStatus");
      if (started !== revision) return;
      if (result.ok) {
        streaming = result.data.outputActive === true;
        sync();
      } else obsTimer = setTimeout(readStream, 3000);
    }
    api.onObs?.((message) => {
      if (message.type === "connection") {
        revision++;
        clearTimeout(obsTimer);
        connected = message.connected;
        streaming = null;
        sync();
        if (connected && next.autoConnect) void readStream();
      } else if (message.eventType === "StreamStateChanged") {
        const { outputState, outputActive } = message.data;
        // つなぎ直し中も同じ配信。開始と停止が済んだところで切り替える。
        if (outputState && !["OBS_WEBSOCKET_OUTPUT_STARTED", "OBS_WEBSOCKET_OUTPUT_STOPPED", "OBS_WEBSOCKET_OUTPUT_RECONNECTED"].includes(outputState)) return;
        revision++;
        clearTimeout(obsTimer);
        streaming = outputActive === true;
        if (next.autoConnect) sync();
      }
    });
    api.onCommand((id) => {
      if (id !== "ttsTest") return;
      if (usingApp) return { ok: false, error: "配信モニター（アプリ）で読み上げを試してください" };
      if (waiting) return { ok: false, error: waitText() };
      reading.test();
    });
    api.onSettings((settings) => {
      const autoChanged = next.autoConnect !== settings.autoConnect;
      if (next.markFirst !== false && settings.markFirst === false) {
        list = list.map((item) => {
          if (!item.first) return item;
          const { first, ...rest } = item;
          return rest;
        });
      }
      next = settings;
      if (autoChanged) {
        revision++;
        clearTimeout(obsTimer);
        if (connected && next.autoConnect) void readStream();
      }
      sync();
    });
    if (monitorApp) {
      const updateApp = (state) => { appState = state; sync(); };
      monitorApp.onChange(updateApp);
      monitorApp.state().then((state) => {
        if (!appState) updateApp(state);
      }, () => {
        if (!appState) updateApp({ state: "none" });
      });
    }
    sync();
  }

  if (typeof lfx !== "undefined") startComments(lfx);
  // Node でも取り出し・判定と読み上げを確かめられるようにする。
  if (typeof module !== "undefined") module.exports = {
    youtubeTarget, twitchChannel, youtubeChat, youtubePage, youtubeLive, ircLine, twitchItem, mergeItems, speechText,
    youtubeViewerCount, youtubePageViewers, youtubeMetadataViewers, twitchViewers, twitchMembership, twitchMembershipNotices,
    createFirstComments, createViewerStats, createReading,
  };
})();
